sys_script_include.script:
var MappingEngine = Class.create();
MappingEngine.prototype = {

    initialize: function () {
        this.values = new ValueMapper();
        this.TX = Constants.CHOICE.MAPPING_TRANSFORM;
    },

    // mappingRef: mapping.code or sys_id. source: parsed payload object.
    // Returns { mapping, rows: [{ rule, target_path, target_table, target_column,
    //   value, context_index }], errors: [] }. Nothing is written - the caller
    // (ExtractionApplier, renewal baseline copy, an inbound PAS sync) decides.
    transform: function (mappingRef, source) {
        var mapping = this._mapping(mappingRef);
        var result = { mapping: mapping ? mapping.getUniqueValue() : '', rows: [], errors: [] };
        if (!mapping) {
            result.errors.push('mapping not found: ' + mappingRef);
            return result;
        }
        var rule = new GlideRecord(Constants.TABLE.MAPPING_RULE);
        rule.addQuery('mapping', mapping.getUniqueValue());
        rule.addQuery('active', true);
        rule.orderBy('sequence');
        rule.query();
        while (rule.next())
            this._apply(rule, source, result);
        return result;
    },

    // Groups rows into records: { '<table>#<context_index>': { table, index, values:{col:val} } }
    toRecords: function (rows) {
        var out = {};
        for (var i = 0; i < rows.length; i++) {
            var r = rows[i];
            if (!r.target_table || !r.target_column)
                continue;
            var key = r.target_table + '#' + r.context_index;
            if (!out[key])
                out[key] = { table: r.target_table, index: r.context_index, values: {} };
            out[key].values[r.target_column] = r.value;
        }
        return out;
    },

    _mapping: function (ref) {
        var gr = new GlideRecord(Constants.TABLE.MAPPING);
        if (gr.get(ref))
            return gr;
        gr = new GlideRecord(Constants.TABLE.MAPPING);
        gr.addQuery('code', ref);
        gr.addQuery('active', true);
        gr.orderByDesc('version');
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr : null;
    },

    _apply: function (rule, source, result) {
        var ctxPath = String(rule.getValue('context_path') || '');
        var contexts = ctxPath ? this._resolve(source, ctxPath) : [source];
        if (!Array.isArray(contexts))
            contexts = contexts === undefined || contexts === null ? [] : [contexts];
        for (var i = 0; i < contexts.length; i++) {
            var ctx = contexts[i];
            if (!this._conditionMet(String(rule.getValue('condition') || ''), ctx, source))
                continue;
            var value;
            try {
                value = this._value(rule, ctx, source);
            } catch (e) {
                result.errors.push(rule.getValue('target_path') + ': ' + e.message);
                continue;
            }
            if (value === undefined || value === null || value === '')
                value = String(rule.getValue('default_value') || '');
            if (value === '' && ['1', 'true'].indexOf(String(rule.getValue('mandatory'))) > -1) {
                result.errors.push(rule.getValue('target_path') + ': mandatory value missing (context ' + i + ')');
                continue;
            }
            var srcPath = String(rule.getValue('source_path') || '');
            var env = this._envelope(ctx, source, srcPath);
            result.rows.push({
                rule: rule.getUniqueValue(),
                target_path: String(rule.getValue('target_path')),
                target_table: String(rule.getValue('target_table') || ''),
                target_column: String(rule.getValue('target_column') || ''),
                transform: String(rule.getValue('transform') || ''),
                value: value,
                raw: env.value === undefined || env.value === null ? '' : String(env.value),
                confidence: env.confidence, page: env.page, bbox: env.bbox,
                source_ref: !srcPath ? '' : (ctxPath && srcPath.indexOf('$.') !== 0 ? ctxPath.replace(/\[\]$/, '') + '[' + i + '].' + srcPath : srcPath.replace(/^\$\./, '')),
                context_index: ctxPath ? i : 0
            });
        }
    },

    _value: function (rule, ctx, root) {
        var t = String(rule.getValue('transform') || this.TX.DIRECT);
        var param = String(rule.getValue('transform_param') || '');
        var v = this._read(ctx, root, String(rule.getValue('source_path') || ''));
        switch (t) {
            case this.TX.DIRECT:
                return v;
            case this.TX.CONSTANT:
                return param;
            case this.TX.CONCAT:
                var parts = [v];
                var more = String(rule.getValue('source_paths') || '').split(',');
                for (var i = 0; i < more.length; i++) {
                    if (more[i].trim())
                        parts.push(this._read(ctx, root, more[i].trim()));
                }
                return parts.filter(function (p) { return p !== undefined && p !== null && p !== ''; }).join(param || ' ');
            case this.TX.SPLIT:
                var sp = param.split('|');
                var pieces = String(v == null ? '' : v).split(sp[0] || ',');
                return (pieces[parseInt(sp[1], 10) || 0] || '').trim();
            case this.TX.VALUE_MAP:
                return this.values.map(String(rule.getValue('value_map_scheme') || ''), v, false, false);
            case this.TX.LOOKUP:
                return this._lookup(param, v);
            case this.TX.DATE_FORMAT:
                return this._isoDate(v);
            case this.TX.NUMBER_FORMAT:
                var n = parseFloat(String(v == null ? '' : v).replace(/[^0-9.\-]/g, ''));
                return isNaN(n) ? '' : String(n);
            case this.TX.CURRENCY_CONVERT:
                return String(v == null ? '' : v).trim().toLowerCase().substring(0, 3);
            case this.TX.CONDITIONAL:
                return v ? param : '';
            case this.TX.SCRIPT:
                var ev = new GlideScopedEvaluator();
                ev.putVariable('value', v);
                ev.putVariable('context', ctx);
                ev.putVariable('source', root);
                return ev.evaluateScript(rule, 'transform_param', null);
            default:
                throw new Error('unknown transform ' + t);
        }
    },

    // '$.' prefix = from the payload root; otherwise relative to the context item.
    // AI leaves may be envelopes { value, confidence, page, bbox } - the value is unwrapped.
    _read: function (ctx, root, p) {
        var v = this._readRaw(ctx, root, p);
        return this._isEnvelope(v) ? v.value : v;
    },

    _readRaw: function (ctx, root, p) {
        if (!p)
            return undefined;
        if (p.indexOf('$.') === 0)
            return this._resolve(root, p.substring(2));
        return this._resolve(ctx, p);
    },

    _envelope: function (ctx, root, p) {
        var v = this._readRaw(ctx, root, p);
        if (this._isEnvelope(v))
            return { value: v.value, confidence: v.confidence === undefined ? '' : v.confidence, page: v.page === undefined ? '' : v.page, bbox: v.bbox || '' };
        return { value: v, confidence: '', page: '', bbox: '' };
    },

    _isEnvelope: function (v) {
        return v !== null && typeof v === 'object' && !Array.isArray(v) && v.hasOwnProperty('value');
    },

    // Dotted path with [] for arrays: 'locations[].address.city' returns an array.
    _resolve: function (obj, p) {
        var segs = String(p).split('.');
        var cur = [obj];
        var fanned = false;
        for (var i = 0; i < segs.length; i++) {
            var seg = segs[i];
            var isArr = /\[\]$/.test(seg);
            var key = seg.replace(/\[\]$/, '');
            var next = [];
            for (var j = 0; j < cur.length; j++) {
                var o = cur[j];
                if (o === null || o === undefined)
                    continue;
                var val = key ? o[key] : o;
                if (isArr) {
                    fanned = true;
                    if (Array.isArray(val))
                        next = next.concat(val);
                } else {
                    next.push(val);
                }
            }
            cur = next;
        }
        return fanned ? cur : cur[0];
    },

    // condition: 'path=value' or 'path!=value' (path read like source_path).
    _conditionMet: function (cond, ctx, root) {
        if (!cond)
            return true;
        var neg = cond.indexOf('!=') > -1;
        var parts = cond.split(neg ? '!=' : '=');
        var actual = String(this._read(ctx, root, parts[0].trim()) || '');
        var expected = String(parts[1] || '').trim();
        return neg ? actual !== expected : actual === expected;
    },

    // param 'table.field' - returns the sys_id of the first record whose field = value.
    _lookup: function (param, v) {
        if (!v)
            return '';
        var dot = param.lastIndexOf('.');
        var gr = new GlideRecord(param.substring(0, dot));
        if (!gr.isValid())
            throw new Error('lookup table invalid: ' + param);
        gr.addQuery(param.substring(dot + 1), v);
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr.getUniqueValue() : '';
    },

    // Accepts yyyy-mm-dd, mm/dd/yyyy, dd-mm-yyyy, dd.mm.yyyy, ISO date-times.
    _isoDate: function (v) {
        var s = String(v == null ? '' : v).trim();
        var m;
        if ((m = s.match(/^(\d{4})-(\d{2})-(\d{2})/)))
            return m[1] + '-' + m[2] + '-' + m[3];
        if ((m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/)))
            return m[3] + '-' + ('0' + m[1]).slice(-2) + '-' + ('0' + m[2]).slice(-2);
        if ((m = s.match(/^(\d{1,2})[.\-](\d{1,2})[.\-](\d{4})$/)))
            return m[3] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2);
        return '';
    },

    type: 'MappingEngine'
};
